python
def chainInspectionFirstQualifyingSlip(head, k):
    a=head
    out=[]
    node=a
    while node:
        out.append(node.val)
        node=node.next
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int chainInspectionFirstQualifyingSlip(ListNode head, int k) {
    ListNode a=head; List<Integer> out=new ArrayList<>();
    {for(ListNode node=a;node!=null;node=node.next)out.add(node.val);}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
